inv_fact[K] = pow(fact[K], MOD - 2, MOD)
for i in range(K, 0, -1):
    inv_fact[i - 1] = inv_fact[i] * i % MOD

def pack(poly: List[int]) -> int:
    return int.from_bytes(
        b"".join(c.to_bytes(BITS // 8, "little") for c in poly), "little"
    )

